INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (1, 'SuperNimbus', 'Software Development Engineer', '2024-06-01', NULL, 'SuperNimbus provided back end services for gaming projectsby creat custom project to suit the customers need. The application were hosted and created using AWS framework', '/assets/content/SuperNimbus.svg', 'JavaScript, C#, C++, TypeScript, SQL, PostgreSql, Unity, Unreal', 1);
INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (2, 'MasterCard', 'Software Development Engineer II', '2023-02-01', '2024-06-30', 'In MasterCard, I hold the position of Software Engineer II, where I work towards the development and maintenance of the In-Control Commercial Payments (ICCP) Platform, an active platform built with Java, Spring Framework, and Angular frontend. I have been actively involved in the Smart Data Project, a ‘Business-to-Business’ software solution for controlling payments for generated virtual cards.', '/assets/content/mastercard-logo.png', 'Java, Shell Scripting, Linux Administration, Spring Boot, mySQL', 1);
INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (3, 'Ergo (Contract: SBCI Customer Hub)', 'Junior Full Stack Software Developer', '2022-05-01', '2023-02-28', 'I was employed by Ergo, as a contractor for the Strategic Banking Corporation of Ireland (SBCI) to work on an emerging web application for the Irish Financial market, the SBCI customer hub. This application is a way for small businesses to access support for reduced-rate loans, allow for on-lenders to view and access these loan applications, and a system for the internal SBCI team to accept or deny these funding opportunities.', '/assets/content/ergo-logo.png', 'Java, JavaScript, AngularJS, Spring Boot, PSQL, HTML, CSS', 1);
INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (4, 'usheru', 'Full Stack Software Developer Intern', '2020-02-01', '2020-08-31', 'Usheru is a film industry marketing and web services company, they provide many web solutions for film festivals, cinema ticketing services, and film online marketing. I was taken on as a Software Development Intern for six months. Here, I mainly worked on an application that was used to generate web pages and services that would provide ticket booking and show times. This application was created using Java, and we did some work on the generated pages using custom HTML and CSS.', '/assets/content/usheru-logo.png', 'Java, JavaScript, HTML, CSS, PSQL, Linux Scripting', 1);
INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (5, 'Albany Beck Pioneer’s Program', 'Full-Stack Java Training Certificate', '2021-08-01', '2022-02-28', 'The Albany Beck Pioneers Program was a six-month intensive training program, which I attended directly after finishing my degree at The National College of Ireland. The aim of the program was to teach Java EE, SQL, and Spring Framework to graduates looking for employment in the technology industry.', '/assets/content/albany-logo.png', 'Java, Spring Framework, SQL', 1);
INSERT INTO work_experience(id, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (6, 'National College of Ireland', 'BSc (Honours) in Computer Science', '2016-08-01', '2021-05-31', 'I achieved a Grade: of 2:1 in my Bachelor''s Degree in Computer Science in National College of Ireland. I specialized in Software Development. Here are some of the modules and projects I completed in my final 2 years.', '/assets/content/nci-logo.png', '', 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (1, 'About the game', 'text', '', 'This project was made in Unity with C# and Steamworks API, by myself acting as project manager and lead developer, and two other developers, and released on Steam in July of 2024. we received over 15,000 library claims and over 2,500 leaderboard entries. The game is free to Play with no Micro-transactions, so please give it a try', 1, 1);
