INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (7, 'Game Jam Development', 'text', '', 'This was a team submission to GMTK Game Jam 2024, which placed 263rd out of nearly 7000 submitted games. The theme of the Game Jam was “roles reversed”, so we decided to do a reverse on the game ‘Crossy Road’. In ‘Crossy Road’, the player''s aim is to control a chicken to get across a road, in our demo ‘Scrambled Eggs’ the player will place cars to stop waves of chicken from crossing the Road. We expanded on this idea with different car types and different chicken types.<?>The development team I led on this project worked really well together, so we have since decided to continue developing this idea into a full release.We are creating iteration with interesting Chicken roles, Car variations, and Road types. We plan to release it on PC and Mobile.', 7, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (8, 'Play the Game Jam Demo here', 'link', 'https://thejackxbl.itch.io/scrambled-eggs', '', 8, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (9, 'About the project', 'text', '', 'This stock trading platform web application was created using Java, SQL, and Spring Framework. The application was created with a team of four, which was led by me, during my time in the Albany Beck’s Pioneer Program. The application was created to simulate online stock traders/clients, where users can place orders (BUY & SELL) for trading, view their order status, view the trade order history, and access their asset purchases in the wallet.', 1, 2);
